-- The curriculum plan board (Admin → Academy → Curriculum): what each Classroom
-- lesson becomes (keep, rename, update, replace, merge, delete) and where each
-- new video is up to (script, deck, recorded, edited, live), with its links.
-- Current lessons are keyed by lesson_id (one row each, only once decided);
-- new lessons have no lesson_id. Seeded from the Sep 2026 locked decisions and
-- the 20 Oct objection-video plan. Admin-only: service role, no policies.

create table if not exists public.curriculum_plan_items (
  id uuid primary key default gen_random_uuid(),
  lesson_id text null unique,
  course_id text not null,
  section_title text null,
  title text not null default '',
  decision text not null default 'undecided'
    check (decision in ('undecided', 'keep', 'rename', 'update', 'replace', 'merge', 'delete', 'new', 'later', 'reference')),
  -- Row key of the lesson this one goes into: a lesson_id, or 'new:<id>'.
  into_key text null,
  status text not null default 'not_started'
    check (status in ('not_started', 'script', 'deck', 'recorded', 'edited', 'live')),
  placement text not null default 'classroom'
    check (placement in ('classroom', 'in_context', 'both')),
  deck_url text null,
  script_url text null,
  video_url text null,
  source_url text null,
  note text not null default '',
  sort_order int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid null references auth.users (id) on delete set null
);

create index if not exists curriculum_plan_items_course_idx
  on public.curriculum_plan_items (course_id, sort_order);

alter table public.curriculum_plan_items enable row level security;

on conflict (lesson_id) do nothing;

