  (null, 'coach-clients', 'Client Retention: Retain, Renew, and Expand', 'If they want to cancel / if they hit the goal', 'new', null, 'not_started', 'classroom', null, null, 'Rescue, renew, proof, next offer. Add as if-then openings when we rewrite retention. Not a new course.', 80)
) as v (lesson_id, course_id, section_title, title, decision, into_key, status, placement, deck_url, video_url, note, sort_order)
where not exists (
  select 1 from public.curriculum_plan_items p
  where p.lesson_id is null and p.course_id = v.course_id and p.title = v.title
);
